function Get-DataUri([string]$relativePath) {
  $fullPath = Join-Path $publicRoot $relativePath
  $extension = [IO.Path]::GetExtension($fullPath).ToLowerInvariant()
  $mime = @{ '.png' = 'image/png'; '.jpg' = 'image/jpeg'; '.jpeg' = 'image/jpeg'; '.svg' = 'image/svg+xml' }[$extension]
  if (-not $mime) { throw "Unsupported embedded asset: $relativePath" }
  "data:$mime;base64,$([Convert]::ToBase64String([IO.File]::ReadAllBytes($fullPath)))"
}

